    12	
    13	/// Action classes a rule may name. A rule naming anything else is invalid.
    14	pub const ACTION_CLASSES: &[&str] = &[
    15	    "payment.read",
    16	    "payment.create",
    17	    "payment.refund",
    18	    "repo.read",
    19	    "repo.write",
    20	    "communication.external.send",
    21	    "llm.inference",
    22	];
    23	
    24	#[derive(Debug, thiserror::Error)]
    25	pub enum LoadError {
    26	    #[error("invalid TOML: {0}")]
    27	    Toml(#[from] toml::de::Error),
    28	    #[error("unsupported format version {0}; expected 1")]
    29	    UnsupportedFormatVersion(u32),
    30	    #[error("{0} must not be empty or malformed")]
    31	    InvalidField(&'static str),
    32	    #[error("rule {rule} has an invalid {field}")]
    33	    InvalidRule { rule: usize, field: &'static str },
    34	    #[error("rule {rule} names unsupported action class {action_class:?}")]
    35	    UnknownActionClass { rule: usize, action_class: String },
    36	    #[error(
    37	        "rules {first} and {second} overlap with equal specificity but different action classes"
    38	    )]
    39	    ConflictingRules { first: usize, second: usize },
    40	}
    41	
    42	/// An immutable, precompiled collection of mapping rules. Its contents are
    43	/// owned strings and therefore it is `Send + Sync` without special handling.
    44	pub struct Classifier {
    45	    rules: Vec<CompiledRule>,
    46	}
    47	
    48	/// Parse, validate, compile, and combine mapping sets. Configuration conflicts
    49	/// are rejected here, so mapping-file ordering never affects classification.
    50	pub async fn load(sets: &[&str]) -> Result<Classifier, LoadError> {
    51	    let mut rules = Vec::new();
    52	    for input in sets {
    53	        let set = parse(input)?;
    54	        for rule in set.rules {
    55	            let index = rules.len();
    56	            let compiled = CompiledRule::new(
    57	                rule.method.as_deref(),
    58	                &set.host,
    59	                rule.subdomain.as_deref(),
    60	                rule.path.as_deref(),
    61	                rule.action_class,
    62	            )
    63	            .map_err(|error| match error {
    64	                CompileError::Host => LoadError::InvalidRule {
    65	                    rule: index,
    66	                    field: "subdomain",
    67	                },
    68	                CompileError::Method => LoadError::InvalidRule {
    69	                    rule: index,
    70	                    field: "method",
    71	                },
    72	                CompileError::Path => LoadError::InvalidRule {
    73	                    rule: index,
    74	                    field: "path",
    75	                },
    76	            })?;
    77	            rules.push(compiled);
    78	        }
    79	    }
    80	    if let Some((first, second)) = find_conflict(&rules) {
    81	        return Err(LoadError::ConflictingRules { first, second });
    82	    }
    83	    Ok(Classifier { rules })
    84	}
