    26	/// Converts one TOML document to a checked mapping set.
    27	pub(crate) fn parse(input: &str) -> Result<MappingSet, LoadError> {
    28	    let set: MappingSet = toml::from_str(input).map_err(LoadError::Toml)?;
    29	    validate(&set)?;
    30	    Ok(set)
    31	}
    32	
    33	fn validate(set: &MappingSet) -> Result<(), LoadError> {
    34	    if set.format_version != 1 {
    35	        return Err(LoadError::UnsupportedFormatVersion(set.format_version));
    36	    }
    37	    required_text("name", &set.name)?;
    38	    required_text("description", &set.description)?;
    39	    validate_host(&set.host)?;
    40	
    41	    for (index, rule) in set.rules.iter().enumerate() {
    42	        if !ACTION_CLASSES.contains(&rule.action_class.as_str()) {
    43	            return Err(LoadError::UnknownActionClass {
    44	                rule: index,
    45	                action_class: rule.action_class.clone(),
    46	            });
    47	        }
    48	        if let Some(method) = &rule.method {
    49	            if !normalize::method(method) {
    50	                return Err(LoadError::InvalidRule {
    51	                    rule: index,
    52	                    field: "method",
    53	                });
    54	            }
    55	        }
    56	        if let Some(subdomain) = &rule.subdomain {
    57	            if subdomain != "*" && (!is_dns_name(subdomain) || normalize::host(subdomain).is_none())
    58	            {
    59	                return Err(LoadError::InvalidRule {
    60	                    rule: index,
    61	                    field: "subdomain",
    62	                });
    63	            }
    64	        }
    65	        if let Some(path) = &rule.path {
    66	            if normalize::pattern_path(path).is_none() {
    67	                return Err(LoadError::InvalidRule {
    68	                    rule: index,
    69	                    field: "path",
    70	                });
    71	            }
    72	        }
    73	    }
    74	    Ok(())
    75	}
    76	
    77	fn required_text(field: &'static str, value: &str) -> Result<(), LoadError> {
    78	    if value.trim().is_empty() || value.chars().any(char::is_control) {
    79	        Err(LoadError::InvalidField(field))
    80	    } else {
    81	        Ok(())
    82	    }
    83	}
    84	
    85	fn validate_host(host: &str) -> Result<(), LoadError> {
    86	    // Mapping hosts name an origin, not an HTTP authority. Ports and trailing
    87	    // dots are accepted for request authorities but create duplicate mapping
    88	    // identities, so reject them here.
    89	    if !host.contains(':')
    90	        && !host.ends_with('.')
    91	        && normalize::host(host).is_some()
    92	        && is_dns_name(host)
    93	    {
    94	        Ok(())
    95	    } else {
    96	        Err(LoadError::InvalidField("host"))
    97	    }
    98	}
    99	
   100	fn is_dns_name(value: &str) -> bool {
   101	    !value.is_empty()
   102	        && value.len() <= 253
   103	        && value.split('.').all(|label| {
   104	            !label.is_empty()
   105	                && label.len() <= 63
   106	                && !label.starts_with('-')
   107	                && !label.ends_with('-')
   108	                && label
   109	                    .bytes()
   110	                    .all(|byte| byte.is_ascii_alphanumeric() || byte == b'-')
   111	        })
   112	}
