    42	/// An immutable, precompiled collection of mapping rules. Its contents are
    43	/// owned strings and therefore it is `Send + Sync` without special handling.
    44	pub struct Classifier {
    45	    rules: Vec<CompiledRule>,
    46	}
    47	
    48	/// Parse, validate, compile, and combine mapping sets. Configuration conflicts
    49	/// are rejected here, so mapping-file ordering never affects classification.
    50	pub async fn load(sets: &[&str]) -> Result<Classifier, LoadError> {
    51	    let mut rules = Vec::new();
    52	    for input in sets {
    53	        let set = parse(input)?;
    54	        for rule in set.rules {
    55	            let index = rules.len();
    56	            let compiled = CompiledRule::new(
    57	                rule.method.as_deref(),
    58	                &set.host,
    59	                rule.subdomain.as_deref(),
    60	                rule.path.as_deref(),
    61	                rule.action_class,
    62	            )
    63	            .map_err(|error| match error {
    64	                CompileError::Host => LoadError::InvalidRule {
    65	                    rule: index,
    66	                    field: "subdomain",
    67	                },
    68	                CompileError::Method => LoadError::InvalidRule {
    69	                    rule: index,
    70	                    field: "method",
    71	                },
    72	                CompileError::Path => LoadError::InvalidRule {
    73	                    rule: index,
    74	                    field: "path",
    75	                },
    76	            })?;
    77	            rules.push(compiled);
    78	        }
    79	    }
    80	    if let Some((first, second)) = find_conflict(&rules) {
    81	        return Err(LoadError::ConflictingRules { first, second });
    82	    }
    83	    Ok(Classifier { rules })
    84	}
    85	
    86	impl Classifier {
    87	    /// Classifies a request. Malformed input is deliberately unclassified
    88	    /// rather than coerced into a potentially broader rule.
    89	    pub async fn classify(&self, method: &str, host: &str, path: &str) -> Option<&str> {
    90	        if !normalize::method(method) {
    91	            return None;
    92	        }
    93	        let host = normalize::host(host)?;
    94	        let path = normalize::request_path(path)?;
    95	        self.rules
    96	            .iter()
    97	            .filter(|rule| rule.matches(method, &host, &path))
    98	            .max_by(|left, right| left.compare_specificity(right))
    99	            .map(|rule| rule.action_class.as_str())
   100	    }
   101	}
     1	//! Parsing and validation for mapping-set TOML documents.
     2	
     3	use serde::Deserialize;
     4	
     5	use crate::{ACTION_CLASSES, LoadError, normalize};
     6	
     7	#[derive(Debug, Deserialize)]
     8	#[serde(deny_unknown_fields)]
     9	pub(crate) struct MappingSet {
    10	    pub(crate) format_version: u32,
    11	    pub(crate) name: String,
    12	    pub(crate) description: String,
    13	    pub(crate) host: String,
    14	    pub(crate) rules: Vec<Rule>,
    15	}
    16	
    17	#[derive(Debug, Deserialize)]
    18	#[serde(deny_unknown_fields)]
    19	pub(crate) struct Rule {
    20	    pub(crate) method: Option<String>,
    21	    pub(crate) subdomain: Option<String>,
    22	    pub(crate) path: Option<String>,
    23	    pub(crate) action_class: String,
    24	}
    25	
    26	/// Converts one TOML document to a checked mapping set.
    27	pub(crate) fn parse(input: &str) -> Result<MappingSet, LoadError> {
    28	    let set: MappingSet = toml::from_str(input).map_err(LoadError::Toml)?;
    29	    validate(&set)?;
    30	    Ok(set)
    31	}
    32	
    33	fn validate(set: &MappingSet) -> Result<(), LoadError> {
    34	    if set.format_version != 1 {
    35	        return Err(LoadError::UnsupportedFormatVersion(set.format_version));
    36	    }
    37	    required_text("name", &set.name)?;
    38	    required_text("description", &set.description)?;
    39	    validate_host(&set.host)?;
    40	
    41	    for (index, rule) in set.rules.iter().enumerate() {
    42	        if !ACTION_CLASSES.contains(&rule.action_class.as_str()) {
    43	            return Err(LoadError::UnknownActionClass {
    44	                rule: index,
    45	                action_class: rule.action_class.clone(),
    46	            });
    47	        }
    48	        if let Some(method) = &rule.method {
    49	            if !normalize::method(method) {
    50	                return Err(LoadError::InvalidRule {
    51	                    rule: index,
    52	                    field: "method",
    53	                });
    54	            }
    55	        }
    56	        if let Some(subdomain) = &rule.subdomain {
    57	            if subdomain != "*" && (!is_dns_name(subdomain) || normalize::host(subdomain).is_none())
    58	            {
    59	                return Err(LoadError::InvalidRule {
    60	                    rule: index,
    61	                    field: "subdomain",
    62	                });
    63	            }
    64	        }
    65	        if let Some(path) = &rule.path {
    66	            if normalize::pattern_path(path).is_none() {
    67	                return Err(LoadError::InvalidRule {
    68	                    rule: index,
    69	                    field: "path",
    70	                });
    71	            }
    72	        }
    73	    }
    74	    Ok(())
    75	}
    76	
    77	fn required_text(field: &'static str, value: &str) -> Result<(), LoadError> {
    78	    if value.trim().is_empty() || value.chars().any(char::is_control) {
    79	        Err(LoadError::InvalidField(field))
    80	    } else {
    81	        Ok(())
    82	    }
    83	}
    84	
    85	fn validate_host(host: &str) -> Result<(), LoadError> {
    86	    // Mapping hosts name an origin, not an HTTP authority. Ports and trailing
    87	    // dots are accepted for request authorities but create duplicate mapping
    88	    // identities, so reject them here.
    89	    if !host.contains(':')
    90	        && !host.ends_with('.')
    91	        && normalize::host(host).is_some()
    92	        && is_dns_name(host)
    93	    {
    94	        Ok(())
    95	    } else {
    96	        Err(LoadError::InvalidField("host"))
    97	    }
    98	}
    99	
   100	fn is_dns_name(value: &str) -> bool {
   101	    !value.is_empty()
   102	        && value.len() <= 253
   103	        && value.split('.').all(|label| {
   104	            !label.is_empty()
   105	                && label.len() <= 63
   106	                && !label.starts_with('-')
   107	                && !label.ends_with('-')
   108	                && label
   109	                    .bytes()
   110	                    .all(|byte| byte.is_ascii_alphanumeric() || byte == b'-')
   111	        })
   112	}
