   260	            Some("/v1/*/refunds/**".into())
   261	        );
   262	        assert_eq!(pattern_path("/v1/*/../admin"), None);
   263	        assert_eq!(pattern_path("/v1/*?debug=true"), Some("/v1/*".into()));
   264	    }
   265	
   266	    #[test]
   267	    fn long_and_arbitrary_utf8_request_inputs_never_panic() {
   268	        assert!(request_path(&format!("/{}", "a".repeat(32 * 1024))).is_some());
   269	        for value in ["\0", "\u{10ffff}", "/\u{10ffff}", "/%"] {
   270	            assert_eq!(request_path(value), None, "{value:?}");
   271	        }
   272	    }
   273	}
