     2	
     3	use std::cmp::Ordering;
     4	
     5	use crate::normalize;
     6	
     7	#[derive(Debug, Clone, PartialEq, Eq)]
     8	pub(crate) enum HostPattern {
     9	    Bare(String),
    10	    Exact(String),
    11	    AnySubdomain(String),
    12	}
    13	
    14	#[derive(Debug, Clone)]
    15	pub(crate) struct CompiledRule {
    16	    pub(crate) method: Option<String>,
    17	    pub(crate) host: HostPattern,
    18	    pub(crate) path: Option<String>,
    19	    pub(crate) action_class: String,
    20	    specificity: Specificity,
    21	}
    22	
    23	#[derive(Debug, Clone, Copy, PartialEq, Eq)]
    24	struct Specificity {
    25	    host: u8,
    26	    path_kind: u8,
    27	    literal_count: usize,
    28	    inverted_wildcard_count: usize,
    29	    literal_prefix: usize,
    30	    method: u8,
    31	}
    32	
    33	impl Ord for Specificity {
    34	    fn cmp(&self, other: &Self) -> Ordering {
    35	        (
    36	            self.host,
    37	            self.path_kind,
    38	            self.literal_count,
    39	            self.inverted_wildcard_count,
    40	            self.literal_prefix,
    41	            self.method,
    42	        )
    43	            .cmp(&(
    44	                other.host,
    45	                other.path_kind,
    46	                other.literal_count,
    47	                other.inverted_wildcard_count,
    48	                other.literal_prefix,
    49	                other.method,
    50	            ))
    51	    }
    52	}
    53	
    54	impl PartialOrd for Specificity {
    55	    fn partial_cmp(&self, other: &Self) -> Option<Ordering> {
    56	        Some(self.cmp(other))
    57	    }
    58	}
