    60	#[derive(Debug)]
    61	pub(crate) enum CompileError {
    62	    Host,
    63	    Method,
    64	    Path,
    65	}
    66	
    67	impl CompiledRule {
    68	    pub(crate) fn new(
    69	        method: Option<&str>,
    70	        base_host: &str,
    71	        subdomain: Option<&str>,
    72	        path: Option<&str>,
    73	        action_class: String,
    74	    ) -> Result<Self, CompileError> {
    75	        let base_host = normalize::host(base_host).ok_or(CompileError::Host)?;
    76	        let host = match subdomain {
    77	            None => HostPattern::Bare(base_host),
    78	            Some("*") => HostPattern::AnySubdomain(base_host),
    79	            Some(value) => {
    80	                let value = normalize::host(value).ok_or(CompileError::Host)?;
    81	                HostPattern::Exact(format!("{value}.{base_host}"))
    82	            }
    83	        };
    84	        let method = match method {
    85	            Some(value) if normalize::method(value) => Some(value.into()),
    86	            Some(_) => return Err(CompileError::Method),
    87	            None => None,
    88	        };
    89	        let path = match path {
    90	            Some(value) => Some(normalize::pattern_path(value).ok_or(CompileError::Path)?),
    91	            None => None,
    92	        };
    93	        let specificity = specificity(&host, method.is_some(), path.as_deref());
    94	        Ok(Self {
    95	            method,
    96	            host,
    97	            path,
    98	            action_class,
    99	            specificity,
   100	        })
   101	    }
   102	
   103	    pub(crate) fn matches(&self, method: &str, host: &str, path: &str) -> bool {
   104	        self.method
   105	            .as_deref()
   106	            .is_none_or(|expected| expected == method)
   107	            && host_matches(&self.host, host)
   108	            && self
   109	                .path
   110	                .as_deref()
   111	                .is_none_or(|pattern| glob_matches(pattern, path))
   112	    }
   113	
   114	    pub(crate) fn compare_specificity(&self, other: &Self) -> Ordering {
   115	        self.specificity.cmp(&other.specificity)
   116	    }
   117	}
   118	
   119	pub(crate) fn find_conflict(rules: &[CompiledRule]) -> Option<(usize, usize)> {
   120	    for (right_index, right) in rules.iter().enumerate() {
   121	        for (left_index, left) in rules[..right_index].iter().enumerate() {
   122	            if left.action_class != right.action_class
   123	                && left.specificity == right.specificity
   124	                && methods_overlap(left.method.as_deref(), right.method.as_deref())
   125	                && hosts_overlap(&left.host, &right.host)
   126	                && paths_overlap(left.path.as_deref(), right.path.as_deref())
   127	            {
   128	                return Some((left_index, right_index));
   129	            }
   130	        }
   131	    }
   132	    None
   133	}
   134	
   135	fn specificity(host: &HostPattern, has_method: bool, path: Option<&str>) -> Specificity {
   136	    let host = u8::from(!matches!(host, HostPattern::AnySubdomain(_)));
   137	    let (path_kind, literal_count, wildcard_count, literal_prefix) = match path {
   138	        None => (0, 0, 0, 0),
   139	        Some(value) if !value.contains('*') => (2, value.len(), 0, value.len()),
   140	        Some(value) => (
   141	            1,
   142	            value.bytes().filter(|byte| *byte != b'*').count(),
   143	            value.bytes().filter(|byte| *byte == b'*').count(),
   144	            value.find('*').unwrap_or(0),
   145	        ),
   146	    };
   147	    Specificity {
   148	        host,
   149	        path_kind,
   150	        literal_count,
   151	        inverted_wildcard_count: usize::MAX - wildcard_count,
   152	        literal_prefix,
   153	        method: u8::from(has_method),
   154	    }
   155	}
   156	
   157	fn host_matches(pattern: &HostPattern, host: &str) -> bool {
   158	    match pattern {
   159	        HostPattern::Bare(expected) | HostPattern::Exact(expected) => expected == host,
   160	        HostPattern::AnySubdomain(base) => host
   161	            .strip_suffix(base)
   162	            .is_some_and(|prefix| prefix.ends_with('.') && prefix.len() > 1),
   163	    }
   164	}
   165	
   166	fn methods_overlap(left: Option<&str>, right: Option<&str>) -> bool {
   167	    left.is_none() || right.is_none() || left == right
   168	}
   169	
   170	fn hosts_overlap(left: &HostPattern, right: &HostPattern) -> bool {
   171	    match (left, right) {
   172	        (HostPattern::Bare(a), HostPattern::Bare(b))
   173	        | (HostPattern::Bare(a), HostPattern::Exact(b))
   174	        | (HostPattern::Exact(a), HostPattern::Bare(b))
   175	        | (HostPattern::Exact(a), HostPattern::Exact(b)) => a == b,
   176	        // These pairs cannot have equal host specificity, but retain correct
   177	        // overlap semantics for callers that want them.
   178	        (HostPattern::AnySubdomain(base), HostPattern::Bare(host))
   179	        | (HostPattern::Bare(host), HostPattern::AnySubdomain(base))
   180	        | (HostPattern::AnySubdomain(base), HostPattern::Exact(host))
   181	        | (HostPattern::Exact(host), HostPattern::AnySubdomain(base)) => {
   182	            host_matches(&HostPattern::AnySubdomain(base.clone()), host)
   183	        }
   184	        (HostPattern::AnySubdomain(a), HostPattern::AnySubdomain(b)) => {
   185	            a == b || a.ends_with(&format!(".{b}")) || b.ends_with(&format!(".{a}"))
   186	        }
   187	    }
   188	}
   189	
   190	fn paths_overlap(left: Option<&str>, right: Option<&str>) -> bool {
   191	    match (left, right) {
   192	        (None, _) | (_, None) => true,
   193	        (Some(left), Some(right)) => globs_overlap(left, right),
   194	    }
   195	}
   196	
   197	pub(crate) fn glob_matches(pattern: &str, value: &str) -> bool {
   198	    let pattern = pattern.as_bytes();
   199	    let value = value.as_bytes();
   200	    let (mut p, mut v, mut star, mut retry) = (0, 0, None, 0);
   201	    while v < value.len() {
   202	        while p < pattern.len() && pattern[p] == b'*' {
   203	            star = Some(p);
   204	            p += 1;
   205	            retry = v;
   206	        }
   207	        if p < pattern.len() && pattern[p] == value[v] {
   208	            p += 1;
   209	            v += 1;
   210	        } else if let Some(star_index) = star {
   211	            p = star_index + 1;
   212	            retry += 1;
   213	            v = retry;
   214	        } else {
   215	            return false;
   216	        }
   217	    }
   218	    while p < pattern.len() && pattern[p] == b'*' {
   219	        p += 1;
   220	    }
   221	    p == pattern.len()
   222	}
   223	
   224	/// Product traversal of two `*` glob NFAs. The sentinel represents any byte
   225	/// not currently present as a literal and keeps the alphabet finite.
   226	fn globs_overlap(left: &str, right: &str) -> bool {
   227	    let (left, right) = (left.as_bytes(), right.as_bytes());
   228	    let mut seen = vec![vec![false; right.len() + 1]; left.len() + 1];
   229	    let mut queue = std::collections::VecDeque::from([(0usize, 0usize)]);
   230	    while let Some((i, j)) = queue.pop_front() {
   231	        if seen[i][j] {
   232	            continue;
   233	        }
   234	        seen[i][j] = true;
   235	        if i == left.len() && j == right.len() {
   236	            return true;
   237	        }
   238	        if left.get(i) == Some(&b'*') {
   239	            queue.push_back((i + 1, j));
   240	        }
   241	        if right.get(j) == Some(&b'*') {
   242	            queue.push_back((i, j + 1));
   243	        }
   244	        let mut alphabet = vec![0];
   245	        if let Some(&byte) = left.get(i).filter(|&&byte| byte != b'*') {
   246	            alphabet.push(byte);
   247	        }
   248	        if let Some(&byte) = right.get(j).filter(|&&byte| byte != b'*') {
   249	            alphabet.push(byte);
   250	        }
   251	        for byte in alphabet {
   252	            let next_left = transition(left, i, byte);
   253	            let next_right = transition(right, j, byte);
   254	            if let (Some(next_left), Some(next_right)) = (next_left, next_right) {
   255	                queue.push_back((next_left, next_right));
   256	            }
   257	        }
   258	    }
   259	    false
   260	}
   261	
   262	fn transition(pattern: &[u8], index: usize, byte: u8) -> Option<usize> {
   263	    match pattern.get(index) {
   264	        Some(b'*') => Some(index),
   265	        Some(&literal) if literal == byte => Some(index + 1),
   266	        _ => None,
   267	    }
   268	}
