   190	fn is_http_token(byte: u8) -> bool {
   191	    byte.is_ascii_alphanumeric()
   192	        || matches!(
   193	            byte,
   194	            b'!' | b'#'
   195	                | b'$'
   196	                | b'%'
   197	                | b'&'
   198	                | b'\''
   199	                | b'*'
   200	                | b'+'
   201	                | b'-'
   202	                | b'.'
   203	                | b'^'
   204	                | b'_'
   205	                | b'`'
   206	                | b'|'
   207	                | b'~'
   208	        )
   209	}
