     1	//! Canonicalization for the three request components accepted by the classifier.
     2	//!
     3	//! This module deliberately accepts only the unambiguous ASCII subset of HTTP
     4	//! authority and path syntax. In particular, IP literals, userinfo, encoded
     5	//! separators, malformed percent escapes, and non-ASCII text are rejected.
     6	
     7	/// Returns a lowercase DNS hostname without one optional trailing dot or port.
     8	pub(crate) fn host(input: &str) -> Option<String> {
     9	    if input.is_empty() || !input.is_ascii() || input.contains('@') {
    10	        return None;
    11	    }
    12	
    13	    let (name, port) = match input.rsplit_once(':') {
    14	        Some((name, port)) => (name, Some(port)),
    15	        None => (input, None),
    16	    };
    17	    if let Some(port) = port {
    18	        if port.is_empty() || !port.bytes().all(|byte| byte.is_ascii_digit()) {
    19	            return None;
    20	        }
    21	        // Parsing also rejects values outside the TCP/UDP port range.
    22	        if port.parse::<u16>().is_err() {
    23	            return None;
    24	        }
    25	    }
    26	
    27	    let name = name.strip_suffix('.').unwrap_or(name);
    28	    if !is_dns_name(name) || name.parse::<std::net::Ipv4Addr>().is_ok() {
    29	        return None;
    30	    }
    31	    Some(name.to_ascii_lowercase())
    32	}
    33	
    34	/// Validates an HTTP token. HTTP methods are intentionally not case folded.
    35	pub(crate) fn method(input: &str) -> bool {
    36	    !input.is_empty() && input.bytes().all(is_http_token)
    37	}
    38	
    39	/// Normalizes a request path. Empty input represents the origin-form `/`.
    40	pub(crate) fn request_path(input: &str) -> Option<String> {
    41	    let end = input.find(['?', '#']).unwrap_or(input.len());
    42	    let path = &input[..end];
    43	    if path.is_empty() {
    44	        return Some("/".into());
    45	    }
    46	    normalize_path(path, false)
    47	}
    48	
    49	/// Normalizes a configuration path pattern while retaining literal `*` wildcards.
    50	pub(crate) fn pattern_path(input: &str) -> Option<String> {
    51	    let end = input.find(['?', '#']).unwrap_or(input.len());
    52	    normalize_path(&input[..end], true)
    53	}
    54	
    55	fn normalize_path(input: &str, pattern: bool) -> Option<String> {
    56	    if input.is_empty() || !input.is_ascii() || !input.starts_with('/') {
    57	        return None;
    58	    }
    59	    validate_percent_escapes(input)?;
    60	
    61	    // A dot segment next to a wildcard cannot be canonicalized soundly: the
    62	    // wildcard can span an unknown number of path segments. Reject rather than
    63	    // assigning it a meaning that a URL client or server may not share.
    64	    if pattern
    65	        && input.contains('*')
    66	        && input
    67	            .split('/')
    68	            .any(|segment| dot_segment_len(segment).is_some())
    69	    {
    70	        return None;
    71	    }
    72	    let canonical = input
    73	        .split('/')
    74	        .map(|segment| match dot_segment_len(segment) {
    75	            Some(1) => ".",
    76	            Some(2) => "..",
    77	            _ => segment,
    78	        })
    79	        .collect::<Vec<_>>()
    80	        .join("/");
    81	    remove_dot_segments(&canonical)
    82	}
    83	
    84	fn validate_percent_escapes(input: &str) -> Option<()> {
    85	    let bytes = input.as_bytes();
    86	    let mut index = 0;
    87	    while index < bytes.len() {
    88	        if bytes[index] == b'%' {
    89	            let hi = *bytes.get(index + 1)?;
    90	            let lo = *bytes.get(index + 2)?;
    91	            let value = (hex(hi)? << 4) | hex(lo)?;
    92	            if matches!(value, b'/' | b'\\') {
    93	                return None;
    94	            }
    95	            index += 3;
    96	        } else {
    97	            index += 1;
    98	        }
    99	    }
   100	    Some(())
   101	}
   102	
   103	fn hex(byte: u8) -> Option<u8> {
   104	    match byte {
   105	        b'0'..=b'9' => Some(byte - b'0'),
   106	        b'a'..=b'f' => Some(byte - b'a' + 10),
   107	        b'A'..=b'F' => Some(byte - b'A' + 10),
   108	        _ => None,
   109	    }
   110	}
   111	
   112	fn dot_segment_len(segment: &str) -> Option<usize> {
   113	    let mut bytes = Vec::with_capacity(segment.len());
   114	    let raw = segment.as_bytes();
   115	    let mut index = 0;
   116	    while index < raw.len() {
   117	        if raw[index] == b'%' {
   118	            let (&hi, &lo) = raw.get(index + 1).zip(raw.get(index + 2))?;
   119	            let value = hex(hi).zip(hex(lo)).map(|(hi, lo)| (hi << 4) | lo)?;
   120	            bytes.push(value);
   121	            index += 3;
   122	        } else {
   123	            bytes.push(raw[index]);
   124	            index += 1;
   125	        }
   126	    }
   127	    match bytes.as_slice() {
   128	        b"." => Some(1),
   129	        b".." => Some(2),
   130	        _ => None,
   131	    }
   132	}
   133	
   134	/// RFC 3986's dot-segment algorithm, operating on validated ASCII text.
   135	fn remove_dot_segments(input: &str) -> Option<String> {
   136	    let mut remaining = input.to_owned();
   137	    let mut output = String::with_capacity(input.len());
   138	    while !remaining.is_empty() {
   139	        if remaining.starts_with("../") {
   140	            remaining.drain(..3);
   141	        } else if remaining.starts_with("./") {
   142	            remaining.drain(..2);
   143	        } else if remaining == "/." {
   144	            remaining.replace_range(.., "/");
   145	        } else if remaining.starts_with("/./") {
   146	            remaining.replace_range(..3, "/");
   147	        } else if remaining == "/.." {
   148	            remaining.replace_range(.., "/");
   149	            pop_last_segment(&mut output);
   150	        } else if remaining.starts_with("/../") {
   151	            remaining.replace_range(..4, "/");
   152	            pop_last_segment(&mut output);
   153	        } else if remaining == "." || remaining == ".." {
   154	            remaining.clear();
   155	        } else {
   156	            let end = if let Some(stripped) = remaining.strip_prefix('/') {
   157	                stripped.find('/').map_or(remaining.len(), |i| i + 1)
   158	            } else {
   159	                remaining.find('/').unwrap_or(remaining.len())
   160	            };
   161	            output.push_str(&remaining[..end]);
   162	            remaining.drain(..end);
   163	        }
   164	    }
   165	    Some(output)
   166	}
   167	
   168	fn pop_last_segment(output: &mut String) {
   169	    if let Some(index) = output.rfind('/') {
   170	        output.truncate(index);
   171	    } else {
   172	        output.clear();
   173	    }
   174	}
   175	
   176	fn is_dns_name(value: &str) -> bool {
   177	    !value.is_empty()
   178	        && value.len() <= 253
   179	        && value.split('.').all(|label| {
   180	            !label.is_empty()
   181	                && label.len() <= 63
   182	                && !label.starts_with('-')
   183	                && !label.ends_with('-')
   184	                && label
   185	                    .bytes()
   186	                    .all(|byte| byte.is_ascii_alphanumeric() || byte == b'-')
   187	        })
   188	}
   189	
   190	fn is_http_token(byte: u8) -> bool {
   191	    byte.is_ascii_alphanumeric()
   192	        || matches!(
   193	            byte,
   194	            b'!' | b'#'
   195	                | b'$'
   196	                | b'%'
   197	                | b'&'
   198	                | b'\''
   199	                | b'*'
   200	                | b'+'
   201	                | b'-'
   202	                | b'.'
   203	                | b'^'
   204	                | b'_'
   205	                | b'`'
   206	                | b'|'
   207	                | b'~'
   208	        )
   209	}
