use action_classifier::load;
#[tokio::test]
async fn probe() {
    let mut s = String::from("format_version = 1
name = "P"
host = "acme.com"
");
    for i in 0..400 { s.push_str(&format!("[[rules]]
path = "/api/{i:05}"
action_class = "{}"
", ["repo.read","repo.write"][i%2])); }
    println!("400 exact paths 2 classes: {:?}", load(&[&s]).await.err().map(|e| e.to_string()));
    let mut w = String::from("format_version = 1
name = "W"
host = "acme.com"
");
    for i in 0..400 { w.push_str(&format!("[[rules]]
path = "/api/{i:05}/*"
action_class = "{}"
", ["repo.read","repo.write"][i%2])); }
    println!("400 wildcard-suffix paths 2 classes: {:?}", load(&[&w]).await.err().map(|e| e.to_string()));
