name = "T"
host = "twilio.com"
[[rules]]
subdomain = "api"
method = "POST"
path = "/2010-04-01/Accounts/*/Messages.json"
action_class = "communication.external.send"
[[rules]]
subdomain = "api"
path = "/*"
action_class = "repo.read"
";
